/* minified main.js - basic whitespace removal for faster delivery */
const PRODUCTS=[{id:1,title:'Classic Shirt',brand:'Brand A',price:1299,old:1999,images:['assets/images/product1.svg','assets/images/product2.svg']},{id:2,title:'Denim Jeans',brand:'Brand B',price:1599,old:2199,images:['assets/images/product2.svg','assets/images/product3.svg']},{id:3,title:'Summer Dress',brand:'Brand C',price:999,old:1499,images:['assets/images/product3.svg','assets/images/product1.svg']},{id:4,title:'T-Shirt Pack',brand:'Brand A',price:799,old:999,images:['assets/images/product1.svg','assets/images/product2.svg']},{id:5,title:'Jacket',brand:'Brand B',price:2499,old:3499,images:['assets/images/product2.svg','assets/images/product3.svg']},{id:6,title:'Kurta',brand:'Brand C',price:1199,old:1799,images:['assets/images/product3.svg','assets/images/product1.svg']}];function qs(s,r=document){return r.querySelector(s)}function qsa(s,r=document){return Array.from(r.querySelectorAll(s))}function initCarousel(){const c=qs('#heroCarousel');if(!c)return;const slides=qs('.slides',c);const total=slides.children.length;let i=0;function show(n){slides.style.transform=`translateX(${-n*100}%)`}qs('.carousel-next',c).addEventListener('click',()=>{i=(i+1)%total;show(i)});qs('.carousel-prev',c).addEventListener('click',()=>{i=(i-1+total)%total;show(i)});setInterval(()=>{i=(i+1)%total;show(i)},5e3)}function initMegaMenu(){qsa('.nav-item').forEach(item=>{const name=item.dataset.menu;const mega=qs('.mega',item);if(!mega)return;mega.innerHTML=`<div style="display:flex;gap:18px"><div style="flex:1"><h4>${name.toUpperCase()}</h4><ul style="list-style:none;padding:0;margin:0"><li>Topwear</li><li>Bottomwear</li><li>Ethnic</li><li>Accessories</li></ul></div><div style="width:240px"><img loading="lazy" src="assets/images/hero2.svg" style="width:100%;border-radius:6px"></div></div>`})}function initStickyHeader(){const h=qs('.main-nav');if(!h)return;window.addEventListener('scroll',()=>{h.classList.toggle('sticky',window.scrollY>80)},{passive:!0})}function renderProducts(id,list=PRODUCTS){const root=qs('#'+id);if(!root)return;root.innerHTML='';list.forEach(p=>{const card=document.createElement('article');card.className='product-card';card.innerHTML=`<a href="product.html?pid=${p.id}"><img loading="lazy" width="360" height="220" src="${p.images[0]}" alt="${p.title}" data-alt="${p.images[1]}"></a><div class="product-title">${p.title}</div><div class="brand">${p.brand}</div><div class="price">₹${p.price} <span class="original">₹${p.old}</span></div>`;const img=card.querySelector('img');card.addEventListener('mouseenter',()=>{if(img.dataset.alt)img.src=img.dataset.alt});card.addEventListener('mouseleave',()=>{img.src=p.images[0]});root.appendChild(card)})}function initCategoryPage(){renderProducts('categoryGrid',PRODUCTS.concat(PRODUCTS))}function initProductPage(){const mainImg=qs('#mainProductImg');if(!mainImg)return;qsa('.thumb').forEach(t=>{t.addEventListener('click',()=>{mainImg.src=t.dataset.src})});qsa('.tab-btn').forEach(btn=>{btn.addEventListener('click',()=>{qsa('.tab-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const tab=btn.dataset.tab;qsa('[data-tabcontent]').forEach(cont=>cont.classList.toggle('hidden',cont.getAttribute('data-tabcontent')!==tab))})});const addBtn=qs('#addToCartBtn');if(addBtn){addBtn.addEventListener('click',()=>{const product={id:1,title:qs('#productTitle').textContent,price:1299,qty:1};addToCart(product);updateCartCount();alert('Added to cart')})}}function initFilters(){qsa('.filter-toggle').forEach(btn=>{btn.addEventListener('click',()=>{const body=btn.nextElementSibling;body.style.display=body.style.display==='block'?'none':'block'})})}function getCart(){return JSON.parse(localStorage.getItem('cm_cart')||'[]')}function saveCart(c){localStorage.setItem('cm_cart',JSON.stringify(c))}function addToCart(item){const cart=getCart();const ex=cart.find(c=>c.id===item.id);if(ex)ex.qty+=item.qty;else cart.push(item);saveCart(cart)}function updateCartCount(){const c=getCart().reduce((s,i)=>s+i.qty,0);const el=qs('#cartCount');if(el)el.textContent=c}function initCartPage(){const root=qs('#cartItems');if(!root)return;const cart=getCart();root.innerHTML='';let total=0,items=0;cart.forEach(it=>{items+=it.qty;total+=it.price*it.qty;const el=document.createElement('div');el.className='cart-item';el.innerHTML=`<img loading="lazy" src="assets/images/product1.svg"><div><div>${it.title}</div><div>₹${it.price} x ${it.qty}</div></div>`;root.appendChild(el)});const sc=qs('#summaryCount');if(sc)sc.textContent=items;const st=qs('#summaryTotal');if(st)st.textContent=`₹${total}`}function initNewsletter(){const f=qs('#newsletterForm');if(!f)return;f.addEventListener('submit',e=>{e.preventDefault();alert('Thanks for subscribing');f.reset()})}document.addEventListener('DOMContentLoaded',()=>{initCarousel();initMegaMenu();initStickyHeader();initFilters();initNewsletter();updateCartCount();renderProducts('productGrid');initCategoryPage();initProductPage();initCartPage()});
